inline constexpr unsigned Index(int code) {
    if (code == 0) return 0;
    if (code == 1 || code == 2) return 1;
    if (code == 3) return 2;
    if (code == 45 || code == 48) return 3;
    if (code >= 51 && code <= 57) return 4;
    if ((code >= 61 && code <= 67) || (code >= 80 && code <= 82)) return 5;
    if ((code >= 71 && code <= 77) || code == 85 || code == 86) return 6;
    if (code == 95 || code == 96 || code == 99) return 7;
    return 8;
}
inline bool Expand(std::span<uint8_t> pixels) {
    if (pixels.size() != Width * Height * 4) return false;
    size_t at = 0;
    for (size_t i = 0; i < Coverage.size(); i += 2) {
        if (at + Coverage[i] > Width * Height) return false;
        const auto value = Coverage[i + 1];
        const auto color = Colors[value >> 4];
        for (unsigned j = 0; j < Coverage[i]; ++j, ++at) {
            pixels[at * 4] = color;
            pixels[at * 4 + 1] = color >> 8;
            pixels[at * 4 + 2] = color >> 16;
            pixels[at * 4 + 3] = (value & 15) * 17;
        }
    }
    return at == Width * Height;
}
